window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-03ba5cb68a6bbc6b"]={"versions": [{"id": "FIG-03ba5cb68a6bbc6b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-73b6f536ac19e15f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e8a9adf0b64d9a61", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-0b80c0ffd8c14573", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-95fe3a1f2d7dffcf", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-744cbf66e29c512e", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-ee9e64b5234b4efd", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-826069405ce55614", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-67a73a02d2663734", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-59185e2112f3deb2", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Signalverlaufs- und Timing-Diagramm (zeitdiskretes Zustands- und Wertediagramm).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, Basic Software (BSW), System Services – <strong>Diagnostic Event Manager (Dem)</strong> (Spezifikation: <code>AUTOSAR_SWS_DiagnosticEventManager</code>, R4.2.2).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des internen zählerbasierten Entprellalgorithmus (<code>DemDebounceCounterBased</code>) für Diagnose-Events. Das Diagramm demonstriert die Berechnung des internen <em>Fault Detection Counters</em> (FDC), das Verhalten der Sprungfunktionen (<em>Jump Up</em> / <em>Jump Down</em>) bei Richtungswechseln des Zählers sowie die Qualifizierung des Event-Status (<code>FAILED</code> / <code>PASSED</code>) einschließlich der direkten Status-Reports.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Eingangsschnittstelle (Reports):</strong>\n<ul class=\"fig-list\"><li><code>Dem_SetEventStatus(EventId, EventStatus)</code> (API-Aufruf via BSW-Modul oder SW-C über das <code>DiagnosticMonitor</code>-Interface).\n</li><li>Report-Werte: <code>DEM_EVENT_STATUS_PREFAILED</code>, <code>DEM_EVENT_STATUS_PREPASSED</code>, <code>DEM_EVENT_STATUS_FAILED</code>, <code>DEM_EVENT_STATUS_PASSED</code>.\n</li></ul>\n</li><li><strong>Interne Entität &amp; Datenstruktur (Fault Detection Counter):</strong>\n<ul class=\"fig-list\"><li><code>Fault Detection Counter</code> (FDC): Interner vorzeichenbehafteter Zähler (standardmäßig auf [-128, +127] bzw. [FDC_min, FDC_max] begrenzt; skaliert über <code>Dem_GetFaultDetectionCounter</code>).\n</li><li>Neutrale Referenzlinie: <code>0</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter (<code>DemDebounceCounterBased</code>):</strong>\n<ul class=\"fig-list\"><li><code>DemDebounceCounterIncrementStepSize</code> (<code>step up</code>): Schrittweite bei <code>PREFAILED</code>.\n</li><li><code>DemDebounceCounterDecrementStepSize</code> (<code>step down</code>): Schrittweite bei <code>PREPASSED</code>.\n</li><li><code>DemDebounceCounterFailedThreshold</code> (<code>FDC max</code>): Schwellwert für Fehlerqualifizierung.\n</li><li><code>DemDebounceCounterPassedThreshold</code> (<code>FDC min</code>): Schwellwert für Gut-Qualifizierung.\n</li><li><code>DemDebounceCounterJumpDown</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpDownValue</code>: Aktivierung und Zielwert für den Abwärtssprung.\n</li><li><code>DemDebounceCounterJumpUp</code> (<code>boolean</code>) &amp; <code>DemDebounceCounterJumpUpValue</code>: Aktivierung und Zielwert für den Aufwärtssprung.\n</li></ul>\n</li><li><strong>Ausgangsstatus (Event status):</strong>\n<ul class=\"fig-list\"><li>Qualifizierter Zustand des Events: <code>FAILED</code> (setzt UDS DTC Status-Bit 0 <code>TestFailed</code>) bzw. <code>PASSED</code> (löscht Bit 0 <code>TestFailed</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Inkrementierung (<code>PREFAILED</code> / <code>step up</code>):</strong>\n<ul class=\"fig-list\"><li>Sukzessive Aufrufe von <code>DEM_EVENT_STATUS_PREFAILED</code> inkrementieren den FDC ab <code>0</code> schrittweise um <code>step up</code>.\n</li><li>Bei Erreichen von <code>FDC max</code> kippt der interne Event-Status synchron auf <code>FAILED</code> (schraffierter Bereich).\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Down (<code>jump down</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel der Zählrichtung von aufsteigend zu absteigend durch <code>PREPASSED</code>: Liegt der FDC über <code>jump down value</code>, springt der Zähler sofort auf <code>jump down value</code> (gemäß <code>SWS_Dem_00418</code>, <code>SWS_Dem_00654</code>), anstatt nur um <code>step down</code> dekrementiert zu werden.\n</li><li>Anschließende <code>PREPASSED</code>-Reports dekrementieren regulär um <code>step down</code>.\n</li><li>Erreichen von <code>FDC min</code> qualifiziert den Status als <code>PASSED</code>.\n</li></ul>\n</li><li><strong>Richtungswechsel mit Jump-Up (<code>jump up</code>):</strong>\n<ul class=\"fig-list\"><li>Erster Wechsel von absteigend zu aufsteigend durch <code>PREFAILED</code>: Liegt der FDC unterhalb von <code>jump up value</code>, springt der FDC unmittelbar auf <code>jump up value</code> (<code>SWS_Dem_00677</code>), gefolgt von regulären <code>step up</code>-Inkrementen.\n</li></ul>\n</li><li><strong>Verhinderung redundanter Sprünge (<code>don&#x27;t jump</code>):</strong>\n<ul class=\"fig-list\"><li>Erfolgt ein Richtungswechsel, während der Zähler bereits günstiger steht (d. h. FDC bereits ≤ <code>jump down value</code> bei <code>PREPASSED</code> bzw. FDC ≥ <code>jump up value</code> bei <code>PREFAILED</code>), unterbleibt der Sprung (<code>don&#x27;t jump</code>). Der Zähler wird lediglich um die jeweilige Step-Size verändert.\n</li></ul>\n</li><li><strong>Direkte Qualifizierung / Zähler-Bypass (Unbounced Reports):</strong>\n<ul class=\"fig-list\"><li>Aufruf von <code>DEM_EVENT_STATUS_PASSED</code> (grüner Impuls): Erzwingt den sofortigen Sprung des FDC auf <code>FDC min</code> und schaltet den Event-Status direkt auf <code>PASSED</code>.\n</li><li>Aufruf von <code>DEM_EVENT_STATUS_FAILED</code> (grüner Impuls ganz rechts): Setzt den FDC unter Umgehung des Zählalgorithmus unmittelbar auf <code>FDC max</code> und qualifiziert <code>FAILED</code> (<code>SWS_Dem_00684</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vermeidung von Hystereseverzögerungen:</strong> Jump-Parameter verhindern, dass bei wechselhaftem Fehlverhalten (Intermittent Faults) lange Zyklen zum Verlassen extremer Zählerstände benötigt werden.\n</li><li><strong>API-Verhalten &amp; Priorität:</strong>\n<ul class=\"fig-list\"><li><code>DEM_EVENT_STATUS_FAILED</code> und <code>PASSED</code> überschreiben jeden laufenden Entprellprozess atomar (<code>SWS_Dem_00418</code>).\n</li><li>SW-Cs, die selbst intern entprellen, müssen <code>FAILED</code>/<code>PASSED</code> melden; SW-Cs, die das Dem-Entprellen nutzen, dürfen ausschließlich <code>PREFAILED</code>/<code>PREPASSED</code> melden.\n</li></ul>\n</li><li><strong>Konfigurationsrestriktionen:</strong>\n<ul class=\"fig-list\"><li>Es muss zwingend gelten: $FDC_{min} \\le \\text{jump down value} \\le \\text{jump up value} \\le FDC_{max}$.\n</li><li>Typische Parametrierung: FDC_min = -128, FDC_max = 127, jump down value ≤ 0 ≤ jump up value.\n</li></ul>\n</li><li><strong>Echtzeit- und Taskkontext:</strong>\n<ul class=\"fig-list\"><li>Zählerberechnung und Statustransitionen erfolgen typischerweise im synchronen Kontext von <code>Dem_SetEventStatus</code>. Bei zeitkritischen Monitoren sind die Step- und Jump-Werte so zu dimensionieren, dass die geforderte Fehlerreaktionszeit (Fault Handling Time / FHT) eingehalten wird.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-03ba5cb68a6bbc6b", "to": "FIG-73b6f536ac19e15f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-73b6f536ac19e15f", "to": "FIG-e8a9adf0b64d9a61", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e8a9adf0b64d9a61", "to": "FIG-0b80c0ffd8c14573", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Dokumentenkopf: Ergänzung des AUTOSAR-Logos und des Dokumentenkopfs „Specification of Diagnostic Event Manager | AUTOSAR CP R19-11“.\n</li></ul>"}, {"from": "FIG-0b80c0ffd8c14573", "to": "FIG-95fe3a1f2d7dffcf", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Dokumentenkopf: Aktualisierung der Versionsangabe von „AUTOSAR CP R19-11“ auf „AUTOSAR CP R20-11“.\n</li></ul>"}, {"from": "FIG-95fe3a1f2d7dffcf", "to": "FIG-744cbf66e29c512e", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Dokumentenkopf: Aktualisierung der Versionsangabe von „AUTOSAR CP R20-11“ auf „AUTOSAR CP R21-11“.\n</li></ul>"}, {"from": "FIG-744cbf66e29c512e", "to": "FIG-ee9e64b5234b4efd", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Dokumentenkopf: Aktualisierung der Versionsangabe von „AUTOSAR CP R21-11“ auf „AUTOSAR CP R22-11“.\n</li></ul>"}, {"from": "FIG-ee9e64b5234b4efd", "to": "FIG-826069405ce55614", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-826069405ce55614", "to": "FIG-67a73a02d2663734", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-67a73a02d2663734", "to": "FIG-59185e2112f3deb2", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Zeitachse: Beschriftung <code>t</code> entfallen.\n</li><li>Layout: Dokumentkopf mit AUTOSAR-Logo und Release-Angabe entfallen; oberer Rand zeigt angeschnittene Zeile des Fließtexts.\n</li></ul>"}]};
